package nl.salah.civicsignal.amsterdam;
import jakarta.validation.constraints.Max;import jakarta.validation.constraints.Min;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/sources/amsterdam")
public class AmsterdamController { private final AmsterdamProperties p;private final AmsterdamAdapterService s; public AmsterdamController(AmsterdamProperties p,AmsterdamAdapterService s){this.p=p;this.s=s;} @GetMapping("/status") public java.util.Map<String,Object> status(){return java.util.Map.of("configured",true,"enabled",p.enabled(),"sourceName","Gemeente Amsterdam Open Data","pageSize",p.pageSize(),"maximumRecordsPerImport",p.maximumRecordsPerImport(),"importRunning",s.running(),"apiKeyConfigured",p.apiKey()!=null&&!p.apiKey().isBlank(),"lastImportResult",s.last()==null?"none":s.last());} @PostMapping("/import") public AmsterdamImportResult importNow(@RequestParam(defaultValue="true") boolean dryRun,@RequestParam(required=false) @Min(1) @Max(500) Integer limit){return s.importRecords(Math.min(limit==null?p.maximumRecordsPerImport():limit,p.maximumRecordsPerImport()),dryRun);} }
